<script setup lang="ts">
import {devControlsEnabled} from "../../../config/presentation";
import {computed,ref,watch,onBeforeUnmount} from 'vue';import {isAxiosError} from 'axios';import type {EChartsCoreOption} from 'echarts/core';
import {useRealtimeStore} from '../../../store/useRealtimeStore';import {usePipelineStore} from '../../../store/usePipelineStore';import {leakApi} from '../../../api/leak';import {simulationApi} from '../../../api/realtime';import type {ParkRealtimeState} from '../../../types/realtime';import type {LeakComparison,LeakOption} from '../../../types/leak';import {leakStageLabels} from '../../../types/leak';
import DigitalTwinScene from '../../../components/digital-twin/DigitalTwinScene.vue';import PipelineTopologyGraph from './PipelineTopologyGraph.vue';import ChartCanvas from '../../Operation/components/ChartCanvas.vue';import '../leak.css';
const rt=useRealtimeStore(),assets=usePipelineStore(),dev=devControlsEnabled;const leak=computed(()=>rt.state?.leak);const busy=ref(false),error=ref(''),comparison=ref<LeakComparison|null>(null),selected=ref<LeakOption|null>(null),focus=ref(''),tab=ref<'pressure'|'flow'|'detection'|'risk'>('pressure');let generation=0;
const stale=computed(()=>comparison.value&&(!leak.value?.scenarioId||comparison.value.scenarioId!==leak.value.scenarioId||leak.value.elapsedSimulationSeconds-comparison.value.simulationTime>60||comparison.value.pipelineId!==leak.value.suspectedSegments[0]?.pipeline_id));
function fail(e:unknown){if(isAxiosError(e)){const d=e.response?.data?.detail;return typeof d==='string'?d:d?.message??'请求失败';}return '请求失败，请检查服务与数据库。';}
async function command(fn:()=>Promise<ParkRealtimeState>){if(busy.value)return;busy.value=true;error.value='';try{rt.applyRealtimeState(await fn());}catch(e){error.value=fail(e);}finally{busy.value=false;}}
function start(){if(!dev){window.dispatchEvent(new CustomEvent('twincity-demo-start',{detail:{scenario:'leak'}}));return;}if(window.confirm('启动软件示范管网泄漏，不影响真实管网。'))void command(leakApi.start);}
async function compare(){if(!leak.value?.suspectedSegments[0]||busy.value)return;busy.value=true;error.value='';const g=generation;try{const c=await leakApi.compare(leak.value.suspectedSegments[0].pipeline_id);if(g===generation){comparison.value=c;selected.value=null;}}catch(e){if(g===generation)error.value=fail(e);}finally{if(g===generation)busy.value=false;}}
async function execute(){if(!selected.value||!comparison.value)return;if(window.confirm('仅作用于软件仿真，不控制真实阀门。')){await command(()=>leakApi.execute(comparison.value!.id,selected.value!.id));selected.value=null;}}
watch(()=>leak.value?.scenarioId,()=>{generation++;comparison.value=null;selected.value=null;focus.value='';error.value='';});
watch(()=>leak.value?.confirmedAt,(value,old)=>{if(value&&!old)focus.value=leak.value?.suspectedSegments[0]?.pipeline_id??'';});
watch(()=>rt.state?.valves?.map(v=>v.status).join(','),(n,o)=>{if(n!==o&&comparison.value){error.value='阀门状态已变化，请重新比较隔离方案。';comparison.value=null;selected.value=null;}});
onBeforeUnmount(()=>generation++);
const labels={pressure:'压力 MPa',flow:'管段流量 m³/h',detection:'异常匹配度 0–1',risk:'泄漏规则风险 0–100'};
const chart=computed<EChartsCoreOption>(()=>({animation:false,tooltip:{trigger:'axis'},grid:{left:60,right:25,top:35,bottom:35},xAxis:{type:'value',name:'min',axisLabel:{color:'#9fb9c9'}},yAxis:{type:'value',name:labels[tab.value],min:0,axisLabel:{color:'#9fb9c9'},splitLine:{lineStyle:{color:'#243f51'}}},series:[{name:labels[tab.value],type:'line',showSymbol:false,lineStyle:{color:'#6bc5dc'},data:rt.leakHistory.map(p=>[p.time/60,p[tab.value]])}]}));
</script><template><div class="leak-controls"><button @click="start" :disabled="busy||!!leak?.scenarioId">启动管网泄漏演示</button><button @click="command(()=>leakApi.command('stop'))" :disabled="busy||!leak?.scenarioId||!rt.state?.running">暂停泄漏场景</button><button @click="command(simulationApi.start)" :disabled="busy||!leak?.scenarioId||rt.state?.running">继续泄漏场景</button><button v-if="dev" @click="command(()=>leakApi.command('reset'))" :disabled="busy||!leak?.scenarioId">重置泄漏场景</button><label v-if="dev">仿真速度<select :value="rt.state?.speed" aria-label="泄漏模拟速度" @change="command(()=>simulationApi.speed(Number(($event.target as HTMLSelectElement).value)))"><option :value="1">1×</option><option :value="5">5×</option><option :value="10">10×</option></select></label></div><p class="leak-scope">软件示范管网 · 简化泄漏与拓扑模型，非真实水力求解；定位为异常匹配，不是校准概率。阀门仅仿真。</p><p v-if="error" role="alert">{{error}}</p>
<div class="leak-layout" data-testid="leak-page" :data-stage="leak?.currentStage"><aside class="panel"><h3>疑似管段排名</h3><p v-if="leak?.execution">隔离后保留最近确认的位置证据；当前异常强度见右侧观测。</p><p v-if="!leak?.suspectedSegments.length">观察全网压力与流量，尚未达到疑似阈值。</p><button v-for="(p,i) in leak?.suspectedSegments" :key="p.pipeline_id" class="leak-suspect" :data-suspect="p.pipeline_id" @click="focus=p.pipeline_id"><span>{{i+1}} · {{p.pipeline_id}}</span><strong>{{(p.score*100).toFixed(1)}}%</strong><small>软件匹配度</small></button><h4>拓扑影响建筑</h4><ul data-testid="leak-buildings"><li v-for="b in leak?.affectedBuildings" :key="b.buildingId">{{b.buildingName}}</li></ul><p>服务损失指数 {{((leak?.estimatedServiceLoss??0)*100).toFixed(1)}}%</p><h4>隔离后仍停水</h4><ul><li v-for="b in leak?.interruptedBuildings" :key="b.buildingId">{{b.buildingName}}</li></ul></aside>
<main><DigitalTwinScene v-if="assets.assets.edges.length" :realtime-state="rt.state" :pipeline-network="assets.assets" :focus-pipeline-id="focus||undefined" :pipeline-types="['water']" :leak-preview="selected??undefined" initial-underground @pipeline-select="id=>focus=id"/><div class="panel leak-trends"><div class="leak-controls"><button v-for="(label,key) in labels" :key="key" :aria-pressed="tab===key" @click="tab=key">{{label}}</button></div><ChartCanvas :option="chart" :label="labels[tab]"/><small data-testid="leak-history-count">{{rt.leakHistory.length}} / 1800 点 · 60 仿真分钟</small></div></main>
<aside class="panel leak-observations"><h3>管网泄漏状态</h3><b data-testid="leak-stage">{{leakStageLabels[leak?.currentStage??'NORMAL']}}</b><dl><div><dt>异常匹配度</dt><dd data-testid="leak-detection">{{((leak?.detectionScore??0)*100).toFixed(1)}}%</dd></div><div><dt>上游 / 下游观测压力</dt><dd>{{leak?.upstreamPressure.toFixed(3)}} / {{leak?.downstreamPressure.toFixed(3)}} MPa</dd></div><div><dt>管段观测流量</dt><dd>{{leak?.pipelineFlow.toFixed(2)}} m³/h</dd></div><div><dt>估算泄漏流量</dt><dd data-testid="leak-flow">{{leak?.estimatedLeakFlow.toFixed(2)}} m³/h</dd></div><div><dt>压力下降速度</dt><dd>{{leak?.pressureDropRate.toFixed(3)}} MPa/min</dd></div><div><dt>场景规则风险</dt><dd data-testid="leak-risk">{{leak?.riskScore.toFixed(1)}} / 100</dd></div></dl><p>泄漏 {{leak?.leakStatus}} / 供水 {{leak?.serviceStatus}}</p><p v-if="leak?.currentStage==='STABILIZING'">泄漏受控不等于服务恢复，停水建筑继续保留。</p><ul><li v-for="f in leak?.riskBreakdown" :key="f.key">{{f.key}} · {{f.points.toFixed(1)}} 分</li></ul><button data-testid="leak-compare" @click="compare" :disabled="busy||!leak?.confirmedAt||!!leak?.execution">比较阀门隔离候选</button><p>10× 时建议暂停后比较，避免旧状态过期。</p></aside></div>
<section v-if="comparison" class="panel leak-options" data-testid="leak-options"><h3>隔离候选比较 <small>{{comparison.latencyMs.toFixed(1)}} ms</small></h3><p>{{comparison.method}}</p><p v-if="stale">比较状态已过期，请重新比较。</p><div class="leak-option-grid"><article v-for="o in comparison.options" :key="o.id" :data-option="o.id" :class="{selected:selected?.id===o.id}"><h4>{{o.id}} · {{o.valves.join('、')}}</h4><p>阀门 {{o.valves.length}} 个 · 隔离 {{o.estimatedScope.length}} m</p><p>影响 {{o.affectedBuildings.length}} 栋 · 服务损失指数 {{(o.estimatedServiceLoss*100).toFixed(0)}}%</p><p>{{o.affectedBuildings.map(b=>b.buildingName).join('、')}}</p><button @click="selected=o">预览此隔离范围</button></article></div><button data-testid="leak-execute" @click="execute" :disabled="busy||!selected||stale||!!leak?.execution">模拟执行隔离</button></section>
<PipelineTopologyGraph :network="assets.assets" :types="['water']" :selected="focus" :trace="selected?.isolatedEdges??[]" :suspects="leak?.suspectedSegments??[]" :preview-valves="selected?.valves??[]" :closed-valves="rt.state?.valves?.filter(v=>v.status==='closed').map(v=>v.id)??[]" :isolated-edges="rt.state?.pipelines.filter(p=>p.status==='isolated').map(p=>p.id)??[]" @edge="id=>focus=id"/>
<section class="panel leak-timeline"><h3>检测与处置事件流</h3><ol><li v-for="e in leak?.events" :key="e.sequence"><time>{{new Date(e.timestamp).toLocaleTimeString()}} / {{(e.simulationTime/60).toFixed(2)}} min</time> {{e.message}}</li></ol><RouterLink to="/review" class="panel-link">稳定后进入事件复盘，完成工单与关闭 →</RouterLink></section></template>
